//! The exact table of a restricted alphabet: how many moves each state near
//! the solved cube needs, found by breadth first search from the solved cube
//! backwards over the alphabet.
//!
//! The table holds every state up to some depth `d` (the last layer may be
//! partial when the entry budget ran out). A state in it has its exact
//! distance; a state not in it needs more than `d` moves, so `d + 1` is an
//! admissible bound. When the search runs out of states before the budget, the
//! table holds the whole group generated by the alphabet, a state that is not
//! in it cannot be solved with the alphabet at all, and every distance is
//! exact.
//!
//! States are 54 sticker colours, kept by a 64-bit hash with the distance in
//! the low byte of the slot (about 14 bytes an entry). Two states with one
//! hash would give a wrong distance; with a few million entries that chance
//! is below one in a billion, and every answer is replayed before it is
//! returned.

use std::time::Instant;

use super::letters::{apply, Letters, State};

/// An open-addressing set of `(hash, distance)` pairs.
pub(super) struct Slots {
    slots: Vec<u64>,
    len: usize,
}

fn tag(hash: u64) -> u64 {
    (hash | 0x100) & !0xff
}

impl Slots {
    fn new() -> Slots {
        Slots {
            slots: vec![0; 1 << 12],
            len: 0,
        }
    }

    fn index(&self, hash: u64) -> usize {
        (tag(hash).wrapping_mul(0x9E37_79B9_7F4A_7C15) >> 24) as usize & (self.slots.len() - 1)
    }

    pub(super) fn get(&self, hash: u64) -> Option<u8> {
        let want = tag(hash);
        let mask = self.slots.len() - 1;
        let mut at = self.index(hash);
        loop {
            let slot = self.slots[at];
            if slot == 0 {
                return None;
            }
            if slot & !0xff == want {
                return Some(slot as u8);
            }
            at = (at + 1) & mask;
        }
    }

    /// Adds the state unless it is known; whether it was new.
    fn insert(&mut self, hash: u64, distance: u8) -> bool {
        if self.len * 10 >= self.slots.len() * 7 {
            self.grow();
        }
        let want = tag(hash);
        let mask = self.slots.len() - 1;
        let mut at = self.index(hash);
        loop {
            let slot = self.slots[at];
            if slot == 0 {
                self.slots[at] = want | u64::from(distance);
                self.len += 1;
                return true;
            }
            if slot & !0xff == want {
                return false;
            }
            at = (at + 1) & mask;
        }
    }

    fn grow(&mut self) {
        let doubled = vec![0; self.slots.len() * 2];
        let old = std::mem::replace(&mut self.slots, doubled);
        let mask = self.slots.len() - 1;
        for slot in old.into_iter().filter(|&s| s != 0) {
            // The index depends on the tag only, which the slot keeps.
            let mut at = self.index(slot);
            while self.slots[at] != 0 {
                at = (at + 1) & mask;
            }
            self.slots[at] = slot;
        }
    }

    pub(super) fn len(&self) -> usize {
        self.len
    }
}

/// The hash of a state.
pub(super) fn hash(state: &State) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for chunk in state.chunks(8) {
        let mut word = 0u64;
        for &b in chunk {
            word = word << 8 | u64::from(b);
        }
        h = (h ^ word).wrapping_mul(0x9e37_79b9_7f4a_7c15);
        h ^= h >> 29;
    }
    h
}

pub(super) struct Table {
    slots: Slots,
    /// Every state up to this distance is in the table.
    depth: u8,
    /// The table holds the whole group.
    complete: bool,
}

impl Table {
    /// Searches from `solved` over the inverse of every letter until the
    /// table holds `max_entries` states, the deadline passes, or nothing is
    /// left.
    pub(super) fn build(
        letters: &Letters,
        solved: &State,
        max_entries: usize,
        deadline: Option<Instant>,
    ) -> Table {
        let mut slots = Slots::new();
        slots.insert(hash(solved), 0);
        let mut frontier: Vec<State> = vec![*solved];
        let mut depth = 0u8;
        let mut complete = false;
        let mut child = [0u8; super::letters::N];
        'layers: loop {
            let mut next: Vec<State> = Vec::new();
            for (count, state) in frontier.iter().enumerate() {
                if count % 256 == 0 && deadline.is_some_and(|d| Instant::now() >= d) {
                    break 'layers;
                }
                for letter in &letters.letters {
                    apply(&letter.inv, state, &mut child);
                    if slots.insert(hash(&child), depth + 1) {
                        next.push(child);
                        if slots.len() >= max_entries {
                            // The layer is partial: its states are in the
                            // table with exact distances, the rest is not.
                            break 'layers;
                        }
                    }
                }
            }
            if next.is_empty() {
                complete = true;
                break;
            }
            depth += 1;
            if depth == u8::MAX - 1 {
                break;
            }
            frontier = next;
        }
        Table {
            slots,
            depth,
            complete,
        }
    }

    /// The exact distance of a state that is in the table.
    pub(super) fn get(&self, state: &State) -> Option<u8> {
        self.slots.get(hash(state))
    }

    /// A lower bound on the distance of a state: its distance if known, else
    /// one more than the depth the table reaches. For a complete table a
    /// missing state is unreachable.
    pub(super) fn bound(&self, state: &State) -> Bound {
        match self.get(state) {
            Some(d) => Bound::Exact(d),
            None if self.complete => Bound::Unreachable,
            None => Bound::AtLeast(self.depth + 1),
        }
    }

    pub(super) fn is_complete(&self) -> bool {
        self.complete
    }

    pub(super) fn len(&self) -> usize {
        self.slots.len()
    }

    pub(super) fn depth(&self) -> u8 {
        self.depth
    }
}

pub(super) enum Bound {
    Exact(u8),
    AtLeast(u8),
    Unreachable,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engines::restricted::letters::Letters;
    use crate::notation::parse_alphabet;
    use crate::puzzle::{Facelets, PuzzleKind};

    fn solved_state() -> State {
        let mut state = [0u8; 54];
        for (slot, face) in state
            .iter_mut()
            .zip(Facelets::solved(PuzzleKind::Cube3).stickers())
        {
            *slot = *face as u8;
        }
        state
    }

    #[test]
    fn the_half_turn_group_is_found_whole() {
        let alphabet = parse_alphabet("half-turns", PuzzleKind::Cube3).unwrap();
        let letters = Letters::new(&alphabet).unwrap();
        let table = Table::build(&letters, &solved_state(), 10_000_000, None);
        assert!(table.is_complete());
        // The group <U2, D2, F2, B2, L2, R2> has 663,552 elements.
        assert_eq!(table.len(), 663_552);
        assert_eq!(table.depth(), 15);
    }

    #[test]
    fn layers_of_two_generators_grow_by_alternating_faces() {
        let alphabet = parse_alphabet("<R,U>", PuzzleKind::Cube3).unwrap();
        let letters = Letters::new(&alphabet).unwrap();
        // Layer sizes are 1, 6 and 18: after R only a U turn is new. One more
        // entry lets the third layer start, so the second is known whole.
        let table = Table::build(&letters, &solved_state(), 1 + 6 + 18 + 1, None);
        assert_eq!(table.len(), 26);
        assert_eq!(table.depth(), 2);
    }

    #[test]
    fn a_small_budget_leaves_a_partial_table_with_a_bound() {
        let alphabet = parse_alphabet("<R,U>", PuzzleKind::Cube3).unwrap();
        let letters = Letters::new(&alphabet).unwrap();
        let table = Table::build(&letters, &solved_state(), 5_000, None);
        assert!(!table.is_complete());
        assert!(table.len() >= 5_000);
        let mut far = solved_state();
        far.swap(0, 9);
        match table.bound(&far) {
            Bound::AtLeast(d) => assert!(d > 1),
            _ => panic!("a state off the table has a lower bound only"),
        }
        assert!(matches!(table.bound(&solved_state()), Bound::Exact(0)));
    }

    #[test]
    fn slots_grow_and_keep_their_entries() {
        let mut slots = Slots::new();
        for i in 0..100_000u64 {
            assert!(slots.insert(
                i.wrapping_mul(0x2545_F491_4F6C_DD1D) ^ (i << 40),
                (i % 20) as u8
            ));
        }
        for i in 0..100_000u64 {
            let h = i.wrapping_mul(0x2545_F491_4F6C_DD1D) ^ (i << 40);
            assert_eq!(slots.get(h), Some((i % 20) as u8));
        }
        assert_eq!(slots.len(), 100_000);
    }
}
